package com.aicharacter.v3;import java.util.*;
/** Deterministic diagnostics for V0.7 architecture. Mutates only the supplied dev-test state. */
public final class V07DevTest{private V07DevTest(){}
 public static String run(WorldState s){StringBuilder b=new StringBuilder("V0.7 DEV TEST\n");b.append("PHYSICAL PATH lakeside->home: ").append(WorldPathPlanner.route(s.world,"lakeside","home_shelter")).append('\n');double oldTime=s.worldMinutes,oldEnergy=s.body.energy,oldAtt=s.relationship.attachment;String oldW=s.environment.weather;double oldI=s.environment.weatherIntensity;s.worldMinutes=16*60;s.environment.weather="CLEAR";s.body.energy=90;s.relationship.attachment=8;b.append("SAME TIME A: ").append(LifeDecisionEngine.choose(s,System.currentTimeMillis()).intention.id).append('\n');s.environment.weather="RAIN";s.environment.weatherIntensity=.9;s.body.energy=18;b.append("SAME TIME B: ").append(LifeDecisionEngine.choose(s,System.currentTimeMillis()).intention.id).append('\n');s.environment.weather="CLEAR";s.body.energy=80;s.relationship.attachment=90;s.lastCatSeenAt=System.currentTimeMillis()-12*3600000L;b.append("SAME TIME C: ").append(LifeDecisionEngine.choose(s,System.currentTimeMillis()).intention.id).append('\n');s.planState=new PlanState();s.planState.status="ACTIVE";s.planState.intentionId="reflect";s.planState.commitment=.4;s.environment.weather="RAIN";s.environment.weatherIntensity=.9;b.append("RECONSIDER: ").append(PlanReconsiderationEngine.evaluate(s,System.currentTimeMillis()).reason).append('\n');int before=s.godInbox.size();GodAttentionEngine.consume(s,new WorldHistoryEntry(System.currentTimeMillis(),"WEATHER","minor_test","minor world event"));b.append("GOD minor silent: ").append(s.godInbox.size()==before?"PASS":"FAIL").append('\n');GodAttentionEngine.consume(s,new WorldHistoryEntry(System.currentTimeMillis(),"GIRL_STARTED_SEARCH","grounded_test","cat search"));b.append("GOD grounded: ").append(s.godInbox.size()>before?"PASS":"FAIL").append('\n');s.catX=1000;s.haruX=1060;b.append("CAMERA: ").append(CatCameraDirector.direct(s).reason).append('\n');s.worldMinutes=oldTime;s.body.energy=oldEnergy;s.relationship.attachment=oldAtt;s.environment.weather=oldW;s.environment.weatherIntensity=oldI;return b.toString();}
}
